INSERT INTO public."user"(steam_id,steam_name,banned,date_created,date_updated) SELECT DISTINCT ON (value.host_id) value.host_id,left(value.host_name,255),false,$2::timestamptz,$2::timestamptz FROM jsonb_to_recordset($1) AS value(host_id bigint,host_name text) ORDER BY value.host_id ON CONFLICT(steam_id) DO UPDATE SET steam_name=excluded.steam_name,date_updated=excluded.date_updated WHERE "user".steam_name IS DISTINCT FROM excluded.steam_name
